def opt_wire(udp=65535, version=0, do=False, options=(), ext_rcode=0, opt_flags=0):
    data = b"".join(struct.pack("!HH", code, len(value)) + value for code, value in options)
    ttl = (ext_rcode << 24) | (version << 16) | (0x8000 if do else 0) | opt_flags
    return b"\x00" + struct.pack("!HHIH", 41, udp, ttl, len(data)) + data


def make_query(qname="a.example.", udp=65535, version=0, do=False,
               options=(), flags=0x0110, opt_count=1, ext_rcode=0,
               opt_flags=0):
